import*as THREE from'three';import{Led,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{grove,terminal}from'./connectors.js';import{addStickers}from'./stickers.js';
class PreviewIndicator extends Led{set(state){if(typeof state==='boolean')state={on:state};else if(typeof state==='string'||typeof state==='number')state={on:true};super.set({...state,color:spec.led.previewColor});}}
function board(host){
 const s=new THREE.Shape(),x=10.5,y=-16,r=3.5,dx=x-8,dy=Math.sqrt(r*r-dx*dx),a=Math.acos(dx/r);
 s.moveTo(-5.45,-26.4);s.lineTo(-7,-26.4);s.lineTo(-x,-23.1);s.lineTo(-x,y-dy);s.absarc(-8,y,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,24.6);s.lineTo(-8,26.4);s.lineTo(8,26.4);s.lineTo(x,24.6);s.lineTo(x,y+dy);s.absarc(8,y,r,a,Math.PI*2-a,false);s.lineTo(x,-23.1);s.lineTo(7,-26.4);s.lineTo(5.45,-26.4);s.lineTo(5.45,-20.5);s.lineTo(-5.45,-20.5);s.closePath();const bore=new THREE.Path();bore.absarc(0,y,2.1,0,Math.PI*2,false);s.holes.push(bore);
 const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:48}),materials.plastic(0x16713e,{roughness:.88}),[0,0,-1.5],'RS485-ISO physical PCB with three scallops,retaining bore and Grove notch');pcb.userData={role:'physical-pcb',scope:'Own photo silhouette and appearance depth reconstruction;no traces or circuit simulation'};
 const dark=materials.plastic(0x252925,{roughness:.8}),metal=materials.metal(0xb4b8a7,{roughness:.46}),ceramic=materials.plastic(0xc2b78c,{roughness:.84}),packages=[];
 const chip=slab(host.body,9.2,8.8,1.65,.18,[4.8,-3.8,-.7],dark,[],.025);chip.name='RS485-ISO U1 CA-IS3082W wide isolated SOIC package';packages.push(chip);
 for(const sign of[-1,1])for(let i=0;i<8;i++)mesh(host.body,new THREE.BoxGeometry(.44,1.4,.22),metal,[4.8+(i-3.5)*1.08,-3.8+sign*4.75,-.35],'RS485-ISO U1 isolated package gull-wing lead');
 const transformerBase=slab(host.body,8.7,10.1,2.0,.3,[-5.45,-3.7,-2.8],dark,[],.05);transformerBase.name='RS485-ISO M1 isolated power transformer physical base';packages.push(transformerBase);
 // Own PCB photo shows a red wound toroid on the power module,not a generic box.
 const toroid=mesh(host.body,new THREE.TorusGeometry(2.88,1.0,20,64),materials.plastic(0x17703d,{roughness:.66}),[-5.45,-3.7,1.1],'RS485-ISO M1 photo-visible green toroidal core');const copper=materials.metal(0xbc3d19,{roughness:.35});
 const windings=[];for(let i=0;i<28;i++){const t=i/28*Math.PI*2,points=[];for(let k=0;k<=24;k++){const p=k/24*Math.PI*2;points.push(new THREE.Vector3(-5.45+(2.88+1.08*Math.cos(p))*Math.cos(t),-3.7+(2.88+1.08*Math.cos(p))*Math.sin(t),1.1+1.08*Math.sin(p)));}windings.push(mesh(host.body,new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),32,.095,7,false),copper,[0,0,0],'RS485-ISO M1 visible red copper winding '+(i+1)));}
 for(const sign of[-1,1])for(let i=0;i<4;i++)mesh(host.body,new THREE.BoxGeometry(.4,.8,.7),metal,[-5.45+(i-1.5)*2.1,-3.7+sign*5.25,-.5],'RS485-ISO isolated transformer pin');
 const regulator=slab(host.body,2.4,3.1,.8,.13,[.4,-11,-.7],dark,[],.02);regulator.name='RS485-ISO U2 MST5333 physical regulator';packages.push(regulator);
 const guards=[];for(const[px,py,w,h,d]of[[-5.3,21.3,4.4,2.7,1.8],[.1,21.3,4.4,2.7,1.8],[-5.3,17.9,4.2,2.2,1.2],[.1,17.9,4.2,2.2,1.2],[1.3,14.8,3.8,2.8,1.2],[7.9,14.7,1.6,4.1,1.0],[-7.6,11.4,1.7,1,.7],[-5.1,8.7,2.1,1,.65],[-1.9,8.7,2.1,1,.65],[4.6,8.7,2.1,1,.65],[-7.5,-10.6,1.8,1,.65],[7.6,-11.5,1.8,1,.65]]){const q=slab(host.body,w,h,d,.1,[px,py,-.7],py>20?ceramic:dark,[],.015);q.name='RS485-ISO fixed protection or decoupling package';guards.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.25,h,.15),metal,[px+sign*(w/2-.1),py,-.6],'RS485-ISO package solder end');}
 for(const y of[1.5,4.1,6.6])for(const x of[1.6,4.1,6.6,8.6])mesh(host.body,new THREE.BoxGeometry(1.1,.6,.45),ceramic,[x,y,-.47],'RS485-ISO small protection/passive package');
 const ledPackage=slab(host.body,1.1,1.6,.55,.08,[-7.35,-22.5,-.7],materials.plastic(0xd8d5ac,{roughness:.5}),[],.01);ledPackage.name='RS485-ISO actual LED1 SMT physical package';return{pcb,chip,transformerBase,toroid,windings,regulator,packages,guards,ledPackage};
}
function indicator(host){const lens=slab(new THREE.Group(),.55,2.7,4.3,.23,[0,0,0],materials.plastic(0xd5d9ce,{roughness:.52}),[],.02);lens.name='RS485-ISO physical indicator light guide behind native narrow slot';const led=host.add(new PreviewIndicator({id:'power-led',label:'Indicator · fixed preview color',mesh:lens,position:spec.led.position,color:spec.led.previewColor,radius:.2,glowSize:2,meta:{role:'externally-driven-visual',colorMode:'fixed-neutral-white-preview',colorConfirmed:false,evidence:'Own official product says Indicator light;own photo shows LED package and native aperture;v1.1 schematic marks LED1 SMT_LED without emitted color.',inferred:'Neutral-white display preview and internal light-guide depth;no official RGB or emitted-color claim.',scope:'Defaults off,external brightness/on only;no automatic power,UART,RS485 or cable response'}}));led.glow.position.z=4.35;return led;}
export function buildRS485ISO(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe6e8e1,{roughness:.78})}),pcb=board(host),input=grove(host),output=terminal(host),powerLed=indicator(host),fixing=screw(host.body,[0,-16,-3.94],'back',1.25);fixing.name='RS485-ISO physical fixed rear retaining hex screw';const labelFront=slab(host.body,15.8,26.7,.1,.35,[0,2.3,3.7],materials.plastic(0xe4e5df,{roughness:.84}),[],.005),labelBack=slab(host.body,16,36,.1,.35,[0,7,-3.9],materials.plastic(0xe4e5df,{roughness:.84}),[],.005);labelFront.name='RS485-ISO real front adhesive label substrate';labelBack.name='RS485-ISO real rear adhesive label substrate';host.rs485ISOAssembly={parts,pcb,input,output,powerLed,fixing,labelFront,labelBack};host.unitStickers=addStickers(host);}
